// Writes robot-sop.ts: the session's code-mode instructions (how to write the robot, how to plan and brief teach_skills), copied from
// 04-walks-home/cluster/sop/*.md as strings, so the agent's instructions carry them in the tab and on a cloud host with no file access to this
// repository. The SOP files are the source; a test holds the generated file equal to what this prints.
//   node scripts/gen-robot-sop.mjs [--check]
import { readFileSync, writeFileSync } from "node:fs";

const here = new URL(".", import.meta.url);
const sop = (f) => readFileSync(new URL(`../../04-walks-home/cluster/sop/${f}`, here), "utf8").trim();
const files = { ROBOT_SOP: sop("robot.md"), TEACH_SOP: sop("teach.md") };
export const generated = `// GENERATED by scripts/gen-robot-sop.mjs from 04-walks-home/cluster/sop/*.md: do not edit; a test holds it equal. Edit the .md files and rerun.
/** How the session writes the robot as code (robot/body.mjs, node robot/build.mjs, build_robot). */
export const ROBOT_SOP: string = ${JSON.stringify(files.ROBOT_SOP)};
/** How the session plans skills and briefs each thread for teach_skills. */
export const TEACH_SOP: string = ${JSON.stringify(files.TEACH_SOP)};
/** What the session's instructions add in code mode: both, in this order. */
export const ROBOT_CODE_INSTRUCTIONS: string = [ROBOT_SOP, TEACH_SOP].join("\\n\\n");
`;
if (process.argv[2] === "--check") {
  const have = readFileSync(new URL("../robot-sop.ts", here), "utf8");
  if (have !== generated) { console.error("robot-sop.ts is out of date: run node scripts/gen-robot-sop.mjs"); process.exit(1); }
} else if (import.meta.url === `file://${process.argv[1]}`) {
  writeFileSync(new URL("../robot-sop.ts", here), generated);
  console.log("wrote robot-sop.ts");
}
